// ── Live refresh overlay (v0.11.0, opt-in — see background/list-refresh.js) ──
// Same pattern as classify/tracker-list.js: `_DB` above is the bundled
// snapshot and is always the fallback; `_live`, when loaded, is checked
// first. A failed/never-attempted refresh degrades to today's behavior.
let _live = null;

export async function loadLiveCookieDbOverlay() {
  try {
    const stored = await chrome.storage.local.get('weblens:liveCookieDb');
    _live = stored['weblens:liveCookieDb'] ?? null;
  } catch { _live = null; }
}

/**
 * Look up a cookie by name against the Open Cookie Database.
 * Provenance of any result: CLASSIFIED — matched against a published database.
 * @param {string} name
 * @returns {{platform, category, description, retention, controller}|null}
 */
export function lookupCookie(name) {
  if (!name) return null;
  const n = name.trim();
  if (_live?.exact[n]) return _live.exact[n];
  if (_DB.exact[n]) return _DB.exact[n];
  if (_live?.wildcard) {
    for (const w of _live.wildcard) if (n.startsWith(w.n)) return w;
  }
  for (const w of _DB.wildcard) {
    if (n.startsWith(w.n)) return w;
  }
  return null;
}
